components.css:
.ds-btn-primary {
  background: oklch(0.47 0.19 263);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  padding: 12px 20px;
  min-height: 44px;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 150ms ease;
}
.ds-btn-primary:hover { background: oklch(0.4 0.17 263); }
.ds-btn-primary:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #ffffff, 0 0 0 4px oklch(0.47 0.19 263);
}

.ds-btn-red {
  background: oklch(0.5 0.215 27);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  padding: 12px 20px;
  min-height: 44px;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 150ms ease;
}
.ds-btn-red:hover { background: oklch(0.42 0.19 27); }
.ds-btn-red:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #ffffff, 0 0 0 4px oklch(0.5 0.215 27);
}

.ds-field {
  position: relative;
  background: oklch(0.995 0.002 260);
  border: 1px solid oklch(0.9 0.022 260);
  border-radius: 8px;
  display: flex;
  align-items: center;
  min-height: 48px;
}
.ds-field-icon {
  width: 18px;
  height: 18px;
  margin-left: 14px;
  color: oklch(0.34 0.055 265);
  flex-shrink: 0;
}
.ds-input {
  flex: 1;
  border: none;
  background: transparent;
  padding: 12px 16px 12px 10px;
  min-height: 46px;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  color: oklch(0.23 0.04 263);
  outline: none;
}
.ds-input::placeholder { color: oklch(0.34 0.055 265); }
.ds-field:focus-within {
  box-shadow: 0 0 0 2px #ffffff, 0 0 0 3px oklch(0.47 0.19 263);
}

.ds-chip-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: oklch(0.5 0.215 27);
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
  min-height: 22px;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.25;
  white-space: nowrap;
}

.ds-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  padding: 3px 10px;
  min-height: 24px;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: 0.02em;
  white-space: nowrap;
}
.ds-status-up { background: oklch(0.47 0.19 263); color: #ffffff; }
.ds-status-down { background: oklch(0.5 0.215 27); color: #ffffff; }
.ds-status-checking { background: oklch(0.96 0.012 260); color: oklch(0.34 0.055 265); }

.ds-card {
  display: block;
  width: 150px;
  background: oklch(0.995 0.002 260);
  border-radius: 8px;
  text-decoration: none;
}
.ds-card-media {
  height: 150px;
  background: oklch(0.96 0.012 260);
  border-radius: 8px;
}
.ds-card-body { padding-top: 10px; }
.ds-card-name {
  margin: 0;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.25;
  color: oklch(0.23 0.04 263);
}
.ds-card-price {
  margin: 2px 0 0;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.75rem;
  font-weight: 600;
  color: oklch(0.34 0.055 265);
}

.ds-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 56px;
  padding: 0 4px;
  border-top: 1px solid oklch(0.9 0.022 260);
  border-bottom: 1px solid oklch(0.9 0.022 260);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
}
.ds-row-name {
  flex: 1;
  font-size: 1.125rem;
  font-weight: 700;
  color: oklch(0.23 0.04 263);
  line-height: 1.2;
}
.ds-cnt {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: oklch(0.5 0.215 27);
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 0.875rem;
  font-weight: 600;
}
.ds-chev { width: 18px; height: 18px; color: oklch(0.34 0.055 265); }
.ds-row:hover .ds-chev { transform: rotate(180deg); }

.ds-wordmark {
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 1.125rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  color: oklch(0.23 0.04 263);
  text-decoration: none;
}
.ds-wordmark span { color: oklch(0.5 0.215 27); }
.ds-nav { display: flex; gap: 16px; margin-top: 8px; }
.ds-navlink {
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.875rem;
  font-weight: 600;
  color: oklch(0.23 0.04 263);
  text-decoration: none;
  padding: 6px 0;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
}
.ds-navlink:hover, .ds-navlink:focus-visible { box-shadow: inset 0 -2px 0 oklch(0.47 0.19 263); }
